// 6 GB / 2048 = 3 MB, clamped (already between 1 and 32 MB), rounded up to a power of two: 4 MB regions.
// Humongous means more than half a region: 2.5 MB > 2 MB, so yes. It takes 1 region (2.5 MB <= 4 MB).
static long regionSize(long maxHeapBytes) {
    long mb = 1024 * 1024;
    long wanted = Math.clamp(maxHeapBytes / 2048, mb, 32 * mb);   // Math.clamp is JDK 21
    long size = mb;
    while (size < wanted) size *= 2;
    return size;
}

